int8_t cuedsounds_do_play = -1;
bool cuedsounds_is_playing = false;
uint32_t cuedsounds_index = 0;
uint8_t cuedsounds_file = 0;
uint32_t cuedsounds_start_index = 0;
uint32_t cuedsounds_stop_index = 0;
uint8_t cuedsounds_volume = 100;
bool cuedsounds_played = false;
bool cuedsounds_audio_update(int32_t *samples, uint16_t num_samples,
                             uint vol_main) {
  if (!cuedsounds_is_playing && cuedsounds_do_play < 0) {
    return cuedsounds_played;
  }
  if (cuedsounds_do_play >= 0 && !cuedsounds_is_playing) {
    cuedsounds_is_playing = true;
    if (cuedsounds_do_play % 17 == 0) {
      cuedsounds_start_index = CUEDSOUNDS_0_START;
      cuedsounds_stop_index = CUEDSOUNDS_0_STOP;
    } else if (cuedsounds_do_play % 17 == 1) {
      cuedsounds_start_index = CUEDSOUNDS_1_START;
      cuedsounds_stop_index = CUEDSOUNDS_1_STOP;
    } else if (cuedsounds_do_play % 17 == 2) {
      cuedsounds_start_index = CUEDSOUNDS_2_START;
      cuedsounds_stop_index = CUEDSOUNDS_2_STOP;
    } else if (cuedsounds_do_play % 17 == 3) {
      cuedsounds_start_index = CUEDSOUNDS_3_START;
      cuedsounds_stop_index = CUEDSOUNDS_3_STOP;
    } else if (cuedsounds_do_play % 17 == 4) {
      cuedsounds_start_index = CUEDSOUNDS_4_START;
      cuedsounds_stop_index = CUEDSOUNDS_4_STOP;
    } else if (cuedsounds_do_play % 17 == 5) {
      cuedsounds_start_index = CUEDSOUNDS_5_START;
      cuedsounds_stop_index = CUEDSOUNDS_5_STOP;
    } else if (cuedsounds_do_play % 17 == 6) {
      cuedsounds_start_index = CUEDSOUNDS_6_START;
      cuedsounds_stop_index = CUEDSOUNDS_6_STOP;
    } else if (cuedsounds_do_play % 17 == 7) {
      cuedsounds_start_index = CUEDSOUNDS_7_START;
      cuedsounds_stop_index = CUEDSOUNDS_7_STOP;
    } else if (cuedsounds_do_play % 17 == 8) {
      cuedsounds_start_index = CUEDSOUNDS_8_START;
      cuedsounds_stop_index = CUEDSOUNDS_8_STOP;
    } else if (cuedsounds_do_play % 17 == 9) {
      cuedsounds_start_index = CUEDSOUNDS_9_START;
      cuedsounds_stop_index = CUEDSOUNDS_9_STOP;
    } else if (cuedsounds_do_play % 17 == 10) {
      cuedsounds_start_index = CUEDSOUNDS_10_START;
      cuedsounds_stop_index = CUEDSOUNDS_10_STOP;
    } else if (cuedsounds_do_play % 17 == 11) {
      cuedsounds_start_index = CUEDSOUNDS_11_START;
      cuedsounds_stop_index = CUEDSOUNDS_11_STOP;
    } else if (cuedsounds_do_play % 17 == 12) {
      cuedsounds_start_index = CUEDSOUNDS_12_START;
      cuedsounds_stop_index = CUEDSOUNDS_12_STOP;
    } else if (cuedsounds_do_play % 17 == 13) {
      cuedsounds_start_index = CUEDSOUNDS_13_START;
      cuedsounds_stop_index = CUEDSOUNDS_13_STOP;
    } else if (cuedsounds_do_play % 17 == 14) {
      cuedsounds_start_index = CUEDSOUNDS_14_START;
      cuedsounds_stop_index = CUEDSOUNDS_14_STOP;
    } else if (cuedsounds_do_play % 17 == 15) {
      cuedsounds_start_index = CUEDSOUNDS_15_START;
      cuedsounds_stop_index = CUEDSOUNDS_15_STOP;
    } else if (cuedsounds_do_play % 17 == 16) {
      cuedsounds_start_index = CUEDSOUNDS_16_START;
      cuedsounds_stop_index = CUEDSOUNDS_16_STOP;
    } else {
      cuedsounds_start_index = CUEDSOUNDS_0_START;
      cuedsounds_stop_index = CUEDSOUNDS_0_STOP;
    }
    cuedsounds_index = cuedsounds_start_index;
    cuedsounds_do_play = -1;
  }
  for (uint16_t i = 0; i < num_samples; i++) {
    int32_t audio = q16_16_multiply_cue(
        (cuedsounds_audio[cuedsounds_index]) << 16, vol_main);
    samples[i * 2 + 0] += audio;
    samples[i * 2 + 1] += audio;
    cuedsounds_index++;
    if (cuedsounds_index >= cuedsounds_stop_index) {
      cuedsounds_is_playing = false;
      cuedsounds_played = true;
      break;
    }
  }
  return cuedsounds_played;
}
